+
+<PageTitle>Product Catalog</PageTitle>
+
+<h1>Product Catalog</h1>
+
+<div class="catalog-layout">
+    @* ── Left Sidebar: Filters ── *@
+    <aside class="filter-sidebar">
+        <h4>Filters</h4>
+
+        @* Category checkboxes *@
+        <div class="filter-section">
+            <h6>Categories</h6>
+            @if (categories is not null)
+            {
+                @foreach (var category in categories)
+                {
+                    <div class="form-check">
+                        <input class="form-check-input" type="checkbox" id="@($"cat-{category}")"
+                               checked="@selectedCategories.Contains(category)"
+                               @onchange="e => ToggleCategory(category, (bool)e.Value!)" />
+                        <label class="form-check-label" for="@($"cat-{category}")">@category</label>
+                    </div>
+                }
+            }
+            else if (!hasError)
+            {
+                <p class="text-muted">Loading categories…</p>
+            }
+        </div>
+
+        @* Price range *@
+        <div class="filter-section">
+            <h6>Price Range</h6>
+            <div class="mb-2">
+                <label for="minPrice" class="form-label">Min Price</label>
+                <input id="minPrice" type="number" class="form-control form-control-sm"
+                       min="0" step="0.01" placeholder="0.00"
+                       @bind="minPrice" />
+            </div>
+            <div class="mb-2">
+                <label for="maxPrice" class="form-label">Max Price</label>
+                <input id="maxPrice" type="number" class="form-control form-control-sm"
+                       min="0" step="0.01" placeholder="No limit"
+                       @bind="maxPrice" />
+            </div>
+        </div>
+
+        @* In Stock Only *@
+        <div class="filter-section">
+            <div class="form-check">
+                <input class="form-check-input" type="checkbox" id="inStockOnly"
+                       @bind="inStockOnly" />
+                <label class="form-check-label" for="inStockOnly">In Stock Only</label>
+            </div>
+        </div>
+
+        @* Filter buttons *@
+        <div class="filter-actions">
+            <button class="btn btn-primary btn-sm w-100 mb-2" @onclick="ApplyFilters" disabled="@isLoading">
+                Apply Filters
+            </button>
+            <button class="btn btn-outline-secondary btn-sm w-100" @onclick="ClearFilters" disabled="@isLoading">
+                Clear Filters
+            </button>
+        </div>
+    </aside>
+
+    @* ── Main Content Area ── *@
+    <section class="catalog-main">
+        @if (hasError)
+        {
+            <div class="alert alert-danger" role="alert">
+                <strong>Error:</strong> @errorMessage
+                <button class="btn btn-link" @onclick="RetryLoad">Retry</button>
+            </div>
+        }
+        else if (isLoading)
+        {
+            <div class="d-flex justify-content-center align-items-center py-5">
+                <div class="spinner-border text-primary" role="status">
+                    <span class="visually-hidden">Loading…</span>
+                </div>
+                <span class="ms-2">Loading products…</span>
+            </div>
+        }
+        else
+        {
+            @* Toolbar *@
+            <div class="catalog-toolbar">
+                <div class="d-flex align-items-center gap-3">
+                    <label for="sortBy" class="form-label mb-0 text-nowrap">Sort by:</label>
+                    <select id="sortBy" class="form-select form-select-sm toolbar-sort-select"
+                            @bind="sortBy" @bind:after="OnSortChanged">
+                        <option value="price_asc">Price: Low to High</option>
+                        <option value="price_desc">Price: High to Low</option>
+                        <option value="name_asc">Name: A–Z</option>
+                        <option value="rating_desc">Rating: Highest</option>
+                    </select>
+                </div>
+                <span class="text-muted showing-label">
+                    @GetShowingLabel()
+                </span>
+            </div>
+
+            @* Product Grid *@
+            @if (pagedResult is not null && pagedResult.Items.Count > 0)
+            {
+                <div class="product-grid">
+                    @foreach (var product in pagedResult.Items)
+                    {
+                        <ProductCard Product="product"
+                                     OnProductSelected="HandleProductSelected"
+                                     OnAddToCart="HandleAddToCart" />
+                    }
+                </div>
+
+                @* Pagination *@
+                @if (totalPages > 1)
+                {
+                    <nav aria-label="Product pagination" class="mt-4">
+                        <ul class="pagination justify-content-center">
+                            <li class="page-item @(currentPage <= 1 ? "disabled" : "")">
+                                <button class="page-link" @onclick="() => GoToPage(currentPage - 1)"
+                                        disabled="@(currentPage <= 1)">
+                                    Previous
+                                </button>
+                            </li>
+                            @foreach (var p in GetPageNumbers())
+                            {
+                                <li class="page-item @(p == currentPage ? "active" : "")">
+                                    <button class="page-link" @onclick="() => GoToPage(p)">@p</button>
+                                </li>
+                            }
+                            <li class="page-item @(currentPage >= totalPages ? "disabled" : "")">
+                                <button class="page-link" @onclick="() => GoToPage(currentPage + 1)"
+                                        disabled="@(currentPage >= totalPages)">
+                                    Next
+                                </button>
+                            </li>
+                        </ul>
+                    </nav>
+                }
+            }
+            else
+            {
+                <div class="alert alert-info text-center my-5" role="alert">
+                    No products found matching your filters.
+                </div>
+            }
+        }
+    </section>
+</div>
+
+@code {
+    private List<string>? categories;
+    private HashSet<string> selectedCategories = new();
+    private decimal? minPrice;
+    private decimal? maxPrice;
+    private bool inStockOnly;
+    private string sortBy = "price_asc";
+
+    private PagedResult<Product>? pagedResult;
+    private int currentPage = 1;
+    private const int PageSize = 12;
+    private int totalPages;
+
+    private bool isLoading = true;
+    private bool hasError;
+    private string? errorMessage;
+
+    protected override async Task OnInitializedAsync()
+    {
+        await LoadInitialDataAsync();
+    }
+
+    private async Task LoadInitialDataAsync()
+    {
+        isLoading = true;
+        hasError = false;
+        errorMessage = null;
+
+        try
+        {
+            var categoriesTask = ProductService.GetCategoriesAsync();
+            var productsTask = SearchProductsAsync();
+
+            categories = await categoriesTask;
+            await productsTask;
+        }
+        catch (Exception ex)
+        {
+            hasError = true;
+            errorMessage = $"Failed to load catalog data. {ex.Message}";
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private async Task SearchProductsAsync()
+    {
+        var filter = new ProductFilter(
+            Categories: selectedCategories.Count > 0 ? selectedCategories.ToList() : null,
+            MinPrice: minPrice,
+            MaxPrice: maxPrice,
+            InStockOnly: inStockOnly
+        );
+
+        pagedResult = await ProductService.SearchAsync(filter, sortBy, currentPage, PageSize);
+        totalPages = (int)Math.Ceiling((double)pagedResult.TotalCount / PageSize);
+    }
+
+    private async Task ApplyFilters()
+    {
+        currentPage = 1;
+        isLoading = true;
+        hasError = false;
+
+        try
+        {
+            await SearchProductsAsync();
+        }
+        catch (Exception ex)
+        {
+            hasError = true;
+            errorMessage = $"Search failed. {ex.Message}";
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private async Task ClearFilters()
+    {
+        selectedCategories.Clear();
+        minPrice = null;
+        maxPrice = null;
+        inStockOnly = false;
+        sortBy = "price_asc";
+        currentPage = 1;
+
+        await ApplyFilters();
+    }
+
+    private void ToggleCategory(string category, bool isChecked)
+    {
+        if (isChecked)
+            selectedCategories.Add(category);
+        else
+            selectedCategories.Remove(category);
+    }
+
+    private async Task OnSortChanged()
+    {
+        currentPage = 1;
+        await ApplyFilters();
+    }
+
+    private async Task GoToPage(int page)
+    {
+        if (page < 1 || page > totalPages || page == currentPage) return;
+
+        currentPage = page;
+        isLoading = true;
+        hasError = false;
+
+        try
+        {
+            await SearchProductsAsync();
+        }
+        catch (Exception ex)
+        {
+            hasError = true;
+            errorMessage = $"Failed to load page. {ex.Message}";
+        }
+        finally
+        {
+            isLoading = false;
+        }
+    }
+
+    private async Task RetryLoad()
+    {
+        await LoadInitialDataAsync();
+    }
+
+    private async Task HandleProductSelected(Product product)
+    {
+        // Parent-level navigation hook; extend with NavigationManager if needed
+        await Task.CompletedTask;
+    }
+
+    private async Task HandleAddToCart(Product product)
+    {
+        // Placeholder for add-to-cart logic
+        await Task.CompletedTask;
+    }
+
+    private string GetShowingLabel()
+    {
+        if (pagedResult is null || pagedResult.TotalCount == 0)
+            return "No products";
+
+        int start = (currentPage - 1) * PageSize + 1;
+        int end = Math.Min(currentPage * PageSize, pagedResult.TotalCount);
+        return $"Showing {start}–{end} of {pagedResult.TotalCount} products";
+    }
