toolArgs.file_text:
.catalog-layout {
    display: flex;
    gap: 1.5rem;
    align-items: flex-start;
}

.filter-sidebar {
    flex: 0 0 25%;
    max-width: 25%;
    background: #f8f9fa;
    border: 1px solid #dee2e6;
    border-radius: 8px;
    padding: 1.25rem;
    position: sticky;
    top: 1rem;
}

.filter-section {
    margin-bottom: 1.25rem;
    padding-bottom: 1rem;
    border-bottom: 1px solid #dee2e6;
}

.filter-section:last-of-type {
    border-bottom: none;
}

.filter-actions {
    margin-top: 1rem;
}

.catalog-main {
    flex: 1;
    min-width: 0;
}

.catalog-toolbar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: 0.75rem;
    margin-bottom: 1.25rem;
    padding: 0.75rem 1rem;
    background: #f8f9fa;
    border-radius: 8px;
}

.toolbar-sort-select {
    width: auto;
    min-width: 200px;
}

.showing-label {
    font-size: 0.9rem;
}

.product-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
    gap: 1.25rem;
}

@media (max-width: 768px) {
    .catalog-layout {
        flex-direction: column;
    }

    .filter-sidebar {
        flex: none;
        max-width: 100%;
        position: static;
    }

    .product-grid {
        grid-template-columns: repeat(auto-fill, minmax(160px, 1fr));
    }
}

